<?php $q=mysqli_query($koneksi, "SELECT p.idpeminjaman,pm.namapeminjam,p.tanggalpinjam FROM peminjaman p JOIN peminjam pm ON pm.idpeminjam=p.idpeminjam WHERE p.status='Dipinjam' ORDER BY p.idpeminjaman DESC"); ?>
